create table RB_RESTRAINT_CONTROL_DETAILS (RESTRAINT_TYPE VARCHAR(3) not null  ,PROD_TYPE VARCHAR(20) not null  ,CHANNEL_MUSTER VARCHAR(200) null  ,TRAN_TYPE_LINK VARCHAR(200) not null  ,NARRATIVE_CODE VARCHAR(50) null  ,BATCH_FLAG VARCHAR(1) not null  ,RES_BRANCH_RANGE VARCHAR(1) not null  ,COUNTER_FLAG VARCHAR(1) not null  ,EXPRESSION VARCHAR(200) null  ,STATUS VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(RESTRAINT_TYPE,PROD_TYPE,TRAN_TYPE_LINK,BATCH_FLAG,RES_BRANCH_RANGE,COUNTER_FLAG));